package report

import (
	"fmt"

	ginkgotypes "github.com/onsi/ginkgo/v2/types"
)

// NestedContents holds information about the nested layers of a Ginkgo testing suite.
//
// NOTE: The JSON report generated by the Ginkgo binary only holds a flat list of reports,
// but for better readability of the generated reports, this is turned into this nested structure.
type NestedContents struct {
	// TODO: check if actually necessary?? can't I just pass the key to the template?
	LayerDescription string
	HasSkipped       bool
	HasFailed        bool
	Contents         map[string]NestedContents
}

// AssignFailedAndSkipped assigns the failed and skipped states for the given Ginkgo spec report.
func (nc *NestedContents) AssignFailedAndSkipped(specReport ginkgotypes.SpecReport) {
	if specReport.State.Is(ginkgotypes.SpecStateFailureStates) && !nc.HasFailed {
		nc.HasFailed = true
	}

	if specReport.State.Is(ginkgotypes.SpecStateSkipped) && !nc.HasSkipped {
		nc.HasSkipped = true
	}
}

// newNestedContents creates a new NestedContents struct and initializes the Contents map.
func newNestedContents() NestedContents {
	return NestedContents{
		Contents: make(map[string]NestedContents),
	}
}

// BuildNestedContents recursively builds a map of nested maps from the given Ginkgo reports.
//
// This is used to convert the typed structure of the Ginkgo reports
// to a nested Markdown or HTML structure.
func BuildNestedContents(reports []ginkgotypes.Report) (NestedContents, error) {
	spec := newNestedContents()

	for _, report := range reports {
		for _, specReport := range report.SpecReports {
			containerHierarchy := specReport.ContainerHierarchyTexts

			// We derive the cleaned text for the leaf and add it to the container hierarchy,
			// for easier looping later on.
			// Otherwise, we would have to handle the leaf node in a follow-up step.
			cleanLeafNode := getCleanLeafNodeText(specReport)
			containerHierarchy = append(containerHierarchy, cleanLeafNode)

			// Assign failed and skipped values for top-level of the report
			spec.AssignFailedAndSkipped(specReport)

			currentNestingLevel := spec
			for _, item := range containerHierarchy {
				// If the item is not yet in the map, create a new map for the underlying levels
				// and add the item to the map.
				if _, found := currentNestingLevel.Contents[item]; !found {
					newContent := newNestedContents()
					newContent.LayerDescription = item
					currentNestingLevel.Contents[item] = newContent
				}

				// Assign the failed and skipped states to the current nesting level
				//
				// NOTE: it's necessary to assign to a variable first and then set into the map,
				// direct assignment to the map entry does not work.
				content := currentNestingLevel.Contents[item]
				content.AssignFailedAndSkipped(specReport)
				currentNestingLevel.Contents[item] = content

				// Move to the next nesting level for the next entry in the container hierarchy
				currentNestingLevel = content
			}
		}
	}

	return spec, nil
}

// getCleanLeafNodeText returns the clean leaf node text for the given Ginkgo spec report.
//
// Example: An It block with the text "should return the correct value" will be converted
// to "it should return the correct value".
func getCleanLeafNodeText(specReport ginkgotypes.SpecReport) string {
	var leafNodeTypeStr string

	leafNodeType := specReport.LeafNodeType
	switch leafNodeType {
	case ginkgotypes.NodeTypeIt:
		leafNodeTypeStr = "it"
	default:
		panic(fmt.Sprintf("unknown leaf node type: %d", leafNodeType))
	}

	leafNodeText := specReport.LeafNodeText
	cleanLeafNode := leafNodeTypeStr + " " + leafNodeText

	return cleanLeafNode
}
